# LapisLLM foundation code examples

def hello_world():
    """Print a greeting."""
print("Hello, World!")

if __name__ == "__main__":
    hello_world()

# Functions and utilities for LapisLLM

def sum_numbers(a: int, b: int) -> int:
    """Return the sum of two numbers."""
    return a + b

def multiply_numbers(a: int, b: int) -> int:
    """Return the product of two numbers."""
    return a * b

def factorial(n: int) -> int:
    """Compute factorial of n."""
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def fibonacci(n: int) -> int:
    """Compute nth Fibonacci number."""
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

# Tests
assert sum_numbers(2, 3) == 5
assert multiply_numbers(3, 4) == 12
assert factorial(5) == 120
assert fibonacci(6) == 8

# Class examples for LapisLLM

class Calculator:
    """Simple calculator class."""
    def __init__(self):
        self.result = 0

    def add(self, value: int) -> "Calculator":
        """Add value to result."""
        self.result += value
        return self

    def subtract(self, value: int) -> "Calculator":
        """Subtract value from result."""
        self.result -= value
        return self

    def get_result(self) -> int:
        """Get current result."""
        return self.result

class Stack:
    """Simple stack implementation."""
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if self.items:
            return self.items.pop()
        return None

    def peek(self):
        if self.items:
            return self.items[-1]
        return None

    def is_empty(self) -> bool:
        return len(self.items) == 0

# Usage examples
calc = Calculator().add(10).add(5).subtract(3)
print(f"Result: {calc.get_result()}")

stack = Stack()
stack.push(1)
stack.push(2)
stack.push(3)
print(f"Peek: {stack.peek()}")
while not stack.is_empty():
    print(f"Pop: {stack.pop()}")

# Loop and iteration examples

def find_primes(limit: int) -> list:
    """Find all prime numbers up to limit."""
    primes = []
    for num in range(2, limit + 1):
        is_prime = True
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes

def print_multiplication_table(n: int):
    """Print n x n multiplication table."""
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            print(f"{i * j:4}", end="")
        print()

# List comprehensions
def square_evens(numbers: list) -> list:
    """Return squares of even numbers."""
    return [x * x for x in numbers if x % 2 == 0]

# Generator
def countdown(n: int):
    """Generator that counts down from n."""
    while n > 0:
        yield n
        n -= 1

# Usage
primes = find_primes(20)
print(f"Primes up to 20: {primes}")
print_multiplication_table(5)
print(f"Squares of evens: {square_evens([1,2,3,4,5,6])}")
print(f"Countdown: {list(countdown(5))}")

# Data structures examples

def merge_dicts(dict1: dict, dict2: dict) -> dict:
    """Merge two dictionaries."""
    result = dict1.copy()
    result.update(dict2)
    return result

def filter_dict(data: dict, keys: list) -> dict:
    """Filter dictionary to only include specified keys."""
    return {k: v for k, v in data.items() if k in keys}

def group_by_key(items: list, key: str) -> dict:
    """Group list of dicts by a key."""
    result = {}
    for item in items:
        if key in item:
            val = item[key]
            if val not in result:
                result[val] = []
            result[val].append(item)
    return result

# Set operations
def union_sets(set1: set, set2: set) -> set:
    return set1 | set2

def intersection_sets(set1: set, set2: set) -> set:
    return set1 & set2

# Usage
car1 = {"make": "Toyota", "model": "Camry", "year": 2020}
car2 = {"make": "Honda", "model": "Civic", "year": 2019}
merged = merge_dicts(car1, {"color": "Blue"})
print(f"Merged: {merged}")

items = [
    {"name": "apple", "type": "fruit"},
    {"name": "carrot", "type": "vegetable"},
    {"name": "banana", "type": "fruit"},
]
grouped = group_by_key(items, "type")
print(f"Grouped: {grouped}")

print(f"Union: {union_sets({1,2,3}, {3,4,5})}")
print(f"Intersection: {intersection_sets({1,2,3}, {3,4,5})}")

# Explain code function
def explain_factorial(n: int) -> int:
    """Compute factorial of n."""
if n <= 1:
    return 1
return n * explain_factorial(n - 1)

